async function generateFacture() {
    const reservationId = factureIdInput.value.trim();
    
    if (!reservationId) {
        factureIdInput.focus();
        return;
    }
    
    factureInputZone.style.display = 'none';
    factureSpinner.style.display = 'block';
    factureError.style.display = 'none';
    factureDisplay.style.display = 'none';
    
    try {
        const response = await fetch(`${API_BASE_URL}/reservation/${reservationId}`);
        
        if (!response.ok) {
            throw new Error('Reservation not found');
        }
        
        const reservationData = await response.json();
        
        const passagers = [];
        const vehicules = [];
        
        for (let i = 1; i <= reservationData.nbPassagers; i++) {
            try {
                const passengerResponse = await fetch(`${API_BASE_URL}/reservation/${reservationId}/passager/${i}`);
                if (passengerResponse.ok) {
                    const passenger = await passengerResponse.json();
                    passagers.push(passenger);
                }
            } catch (error) {
                console.error(`Error fetching passenger ${i}:`, error);
            }
        }
        
        for (let i = 1; i <= reservationData.nbVehicules; i++) {
            try {
                const vehicleResponse = await fetch(`${API_BASE_URL}/reservation/${reservationId}/vehicule/${i}`);
                if (vehicleResponse.ok) {
                    const vehicle = await vehicleResponse.json();
                    vehicules.push(vehicle);
                }
            } catch (error) {
                console.error(`Error fetching vehicle ${i}:`, error);
            }
        }
        
        const fullReservation = {
            reservation: reservationData,
            passagers: passagers,
            vehicules: vehicules
        };
        
        displayFacture(fullReservation);
        
    } catch (error) {
        factureSpinner.style.display = 'none';
        factureError.style.display = 'block';
        factureErrorText.textContent = 'Réservation introuvable. Veuillez vérifier votre identifiant.';
        console.error('Error fetching reservation:', error);
    }
}

function displayFacture(data) {
    factureSpinner.style.display = 'none';
    factureDisplay.style.display = 'block';
    overlayFacture.querySelector('.overlay-content').classList.add('viewing-facture');
    
    const reservation = data.reservation;
    const passagers = data.passagers || [];
    const vehicules = data.vehicules || [];
    
    let totalPassagers = 0;
    let totalVehicules = 0;
    
    let passagersHTML = '';
    if (passagers.length > 0) {
        passagersHTML = `
            <div class="facture-section">
                <h3 class="facture-section-title">Les personnes</h3>
                <table class="facture-table">
                    <thead>
                        <tr>
                            <th>Catégorie</th>
                            <th>Nombre</th>
                            <th>Prix unitaire</th>
                            <th>Prix ligne</th>
                        </tr>
                    </thead>
                    <tbody>
        `;
        
        const passagersByCategory = {};
        passagers.forEach(p => {
            const cat = p.libelleCategorie || 'Non spécifié';
            if (!passagersByCategory[cat]) {
                passagersByCategory[cat] = { count: 0, unitPrice: p.price || 0 };
            }
            passagersByCategory[cat].count++;
        });
        
        Object.keys(passagersByCategory).forEach(cat => {
            const data = passagersByCategory[cat];
            const lineTotal = data.unitPrice * data.count;
            totalPassagers += lineTotal;
            
            passagersHTML += `
                <tr>
                    <td>${cat}</td>
                    <td>${data.count}</td>
                    <td>${data.unitPrice === 0 ? 'gratuit' : data.unitPrice.toFixed(2) + ' €'}</td>
                    <td>${lineTotal.toFixed(2)} €</td>
                </tr>
            `;
        });
        
        passagersHTML += `
                    </tbody>
                </table>
                <div class="facture-subtotal">Sous-total passagers : ${totalPassagers.toFixed(2)} €</div>
            </div>
        `;
    }
    
    let vehiculesHTML = '';
    if (vehicules.length > 0) {
        vehiculesHTML = `
            <div class="facture-section">
                <h3 class="facture-section-title">Les véhicules</h3>
                <table class="facture-table">
                    <thead>
                        <tr>
                            <th>Catégorie</th>
                            <th>Quantité</th>
                            <th>Prix unitaire</th>
                            <th>Prix ligne</th>
                        </tr>
                    </thead>
                    <tbody>
        `;
        
        vehicules.forEach(v => {
            const lineTotal = (v.prix || 0) * (v.quantite || 1);
            totalVehicules += lineTotal;
            
            vehiculesHTML += `
                <tr>
                    <td>${v.libelle || 'Non spécifié'}</td>
                    <td>${v.quantite || 1}</td>
                    <td>${(v.prix || 0).toFixed(2)} €</td>
                    <td>${lineTotal.toFixed(2)} €</td>
                </tr>
            `;
        });
        
        vehiculesHTML += `
                    </tbody>
                </table>
                <div class="facture-subtotal">Sous-total véhicules : ${totalVehicules.toFixed(2)} €</div>
            </div>
        `;
    }
    
    const grandTotal = totalPassagers + totalVehicules;
    
    const today = new Date();
    const factureHTML = `
        <header class="facture-header">
            <img src="media/logo.png" alt="CAN Logo" class="facture-logo">
            <h2 class="facture-title">Facture</h2>
        </header>
        
        <section class="facture-meta">
            <div class="facture-meta-col">
                <div class="facture-meta-label">Date d'émission</div>
                <div class="facture-meta-value">Lorient, le ${today.toLocaleDateString('fr-FR')}</div>
            </div>
            <div class="facture-meta-col">
                <div class="facture-meta-label">N° de réservation</div>
                <div class="facture-meta-value">${reservation.id}</div>
            </div>
            <div class="facture-meta-col">
                <div class="facture-meta-label">Nom</div>
                <div class="facture-meta-value">${reservation.nom || 'N/A'}</div>
            </div>
        </section>
        
        <section class="facture-trip">
            <h3>Informations de traversée</h3>
            <dl class="facture-trip-grid">
                <div class="facture-trip-item">
                    <dt class="facture-trip-label">Liaison :</dt>
                    <dd class="facture-trip-value">${reservation.portDepart} → ${reservation.portArrivee}</dd>
                </div>
                <div class="facture-trip-item">
                    <dt class="facture-trip-label">Date :</dt>
                    <dd class="facture-trip-value">${reservation.date || 'N/A'}</dd>
                </div>
                <div class="facture-trip-item">
                    <dt class="facture-trip-label">Heure de départ :</dt>
                    <dd class="facture-trip-value">${reservation.heure || 'N/A'}</dd>
                </div>
                <div class="facture-trip-item">
                    <dt class="facture-trip-label">Bateau :</dt>
                    <dd class="facture-trip-value">${reservation.bateau || 'N/A'}</dd>
                </div>
            </dl>
        </section>
        
        ${passagersHTML}
        ${vehiculesHTML}
        
        <section class="facture-total">
            <span class="facture-total-label">Prix total</span>
            <span class="facture-total-value">${grandTotal.toFixed(2)} €</span>
        </section>
        
        <footer class="facture-footer">
            <p>Compagnie Alsacienne de Navigation - Port de Lorient, 56100 Lorient</p>
            <p>Merci de votre confiance</p>
            <button class="btn-print" onclick="window.print()">Imprimer la facture</button>
        </footer>
    `;
    
    factureDisplay.innerHTML = factureHTML;
}

