async function showDashboard(route, day, time) {
    openOverlay(overlayDashboard);
    closeOverlay(overlayDisponibilites);
    
    dashboardContainer.innerHTML = '<div class="loading-spinner"><div class="spinner"></div><p>Chargement...</p></div>';
    
    const liaisons = {
        'lorient-groix': { id: 1, name: 'Lorient → Groix' },
        'groix-lorient': { id: 2, name: 'Groix → Lorient' },
        'quiberon-palais': { id: 3, name: 'Quiberon → Le Palais' },
        'palais-quiberon': { id: 4, name: 'Le Palais → Quiberon' }
    };
    
    const liaison = liaisons[route];
    const date = `2025-11-${day.toString().padStart(2, '0')}`;
    
    try {
        const response = await fetch(`${API_BASE_URL}/liaison/${liaison.id}/remplissage/${date}`);
        if (!response.ok) throw new Error('Failed to fetch data');
        
        const data = await response.json();
        const slot = data.find(s => s.heure === time);
        
        if (!slot) {
            dashboardContainer.innerHTML = '<p style="color: var(--primary); text-align: center;">Aucune donnée disponible</p>';
            return;
        }
        
        const passagerPercent = (slot.nbReservationPassagers / slot.capacitePassagers) * 100;
        const vehiculePercent = (slot.nbReservationVoitures / slot.capaciteVoitures) * 100;
        
        const passagerColor = getColorClass(passagerPercent);
        const vehiculeColor = getColorClass(vehiculePercent);
        
        dashboardContainer.innerHTML = `
            <header class="dashboard-route-info">
                <h3 class="dashboard-route-title">${liaison.name}</h3>
                <p class="dashboard-date">Date : ${date} | Heure : ${time}</p>
            </header>
            
            <section class="dashboard-slots">
                <article class="dashboard-slot">
                    <h4 class="dashboard-slot-time">Passagers</h4>
                    <div class="dashboard-metrics">
                        <div class="dashboard-metric">
                            <span class="dashboard-metric-label">Taux de remplissage</span>
                            <div class="dashboard-metric-bar">
                                <div class="dashboard-metric-fill ${passagerColor}" style="width: ${Math.min(passagerPercent, 100)}%; padding-left: ${passagerPercent < 5 ? '0.5rem' : '0'}">
                                    ${passagerPercent.toFixed(1)}%
                                </div>
                            </div>
                            <p style="font-family: 'Lato', sans-serif; font-size: 0.9rem; color: rgba(255,255,255,0.6); margin-top: 0.5rem;">
                                ${slot.nbReservationPassagers} / ${slot.capacitePassagers} passagers
                            </p>
                        </div>
                    </div>
                </article>
                
                <article class="dashboard-slot">
                    <h4 class="dashboard-slot-time">Véhicules</h4>
                    <div class="dashboard-metrics">
                        <div class="dashboard-metric">
                            <span class="dashboard-metric-label">Taux de remplissage</span>
                            <div class="dashboard-metric-bar">
                                <div class="dashboard-metric-fill ${vehiculeColor}" style="width: ${Math.min(vehiculePercent, 100)}%; padding-left: ${vehiculePercent < 5 ? '0.5rem' : '0'}">
                                    ${vehiculePercent.toFixed(1)}%
                                </div>
                            </div>
                            <p style="font-family: 'Lato', sans-serif; font-size: 0.9rem; color: rgba(255,255,255,0.6); margin-top: 0.5rem;">
                                ${slot.nbReservationVoitures} / ${slot.capaciteVoitures} voitures
                            </p>
                        </div>
                    </div>
                </article>
            </section>
        `;
        
    } catch (error) {
        console.error('Error fetching dashboard data:', error);
        dashboardContainer.innerHTML = '<p style="color: #e74c3c; text-align: center;">Erreur de chargement des données</p>';
    }
}

function getColorClass(percent) {
    if (percent > 100) return 'fill-yellow';
    if (percent >= 75) return 'fill-red';
    if (percent >= 50) return 'fill-orange';
    return 'fill-green';
}

