async function loadStatistics() {
    statsContainer.innerHTML = '';
    statsSpinner.style.display = 'block';
    
    try {
        const liaisons = [
            { id: 1, name: 'Lorient → Groix' },
            { id: 2, name: 'Groix → Lorient' },
            { id: 3, name: 'Quiberon → Le Palais' },
            { id: 4, name: 'Le Palais → Quiberon' }
        ];
        
        let totalRevenue = 0;
        let routesHTML = '';
        
        for (const liaison of liaisons) {
            const response = await fetch(`${API_BASE_URL}/liaison/${liaison.id}/chiffreAffaire`);
            if (!response.ok) continue;
            
            const data = await response.json();
            
            const passagerRevenue = data.passagers.chiffreAffaire || 0;
            const vehiculeRevenue = data.vehicules.chiffreAffaire || 0;
            const routeTotal = passagerRevenue + vehiculeRevenue;
            totalRevenue += routeTotal;
            
            routesHTML += `
                <div class="stats-route-card">
                    <h3 class="stats-route-name">${liaison.name}</h3>
                    <div class="stats-route-data">
                        <div class="stats-data-item">
                            <span class="stats-data-label">CA Passagers</span>
                            <span class="stats-data-value revenue">${passagerRevenue.toFixed(2)} €</span>
                        </div>
                        <div class="stats-data-item">
                            <span class="stats-data-label">Nombre passagers</span>
                            <span class="stats-data-value">${data.passagers.nombre}</span>
                        </div>
                        <div class="stats-data-item">
                            <span class="stats-data-label">CA Véhicules</span>
                            <span class="stats-data-value revenue">${vehiculeRevenue.toFixed(2)} €</span>
                        </div>
                        <div class="stats-data-item">
                            <span class="stats-data-label">Quantité véhicules</span>
                            <span class="stats-data-value">${data.vehicules.quantite}</span>
                        </div>
                        <div class="stats-data-item" style="border-top: 2px solid rgba(255,255,255,0.2); padding-top: 0.75rem; margin-top: 0.5rem;">
                            <span class="stats-data-label">Total liaison</span>
                            <span class="stats-data-value revenue">${routeTotal.toFixed(2)} €</span>
                        </div>
                    </div>
                </div>
            `;
        }
        
        statsSpinner.style.display = 'none';
        statsContainer.innerHTML = `
            <section class="stats-global">
                <h3>Chiffre d'affaires global - Novembre 2025</h3>
                <p class="stats-global-value">${totalRevenue.toFixed(2)} €</p>
            </section>
            <section class="stats-routes">
                ${routesHTML}
            </section>
        `;
        
    } catch (error) {
        console.error('Error loading statistics:', error);
        statsSpinner.style.display = 'none';
        statsContainer.innerHTML = '<p style="color: #e74c3c; text-align: center;">Erreur de chargement des statistiques</p>';
    }
}